python3 -c "
import json

# Check for exchange rate data in one of the JSON files
with open('/app/resources/treasury_bulletin_1964_03.json', 'r') as f:
    data = json.load(f)

# Print keys at top level
def explore(obj, indent=0):
    if isinstance(obj, dict):
        for k, v in obj.items():
            print(' ' * indent + str(k))
            if isinstance(v, (dict, list)) and indent < 2:
                explore(v, indent + 2)
    elif isinstance(obj, list) and len(obj) < 10:
        for item in obj[:3]:
            explore(item, indent + 2)

explore(data)
" 2>&1 | head -50
